/*
 * A163603  Numbers k such that prime(k) == 5 (mod 7).
 * https://oeis.org/A163603
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 45, u16 n <= 5000, u32 n <= 5000, u64 n <= 5000,
 *            u128 n <= 5000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computation: a(n) is the index of the n‑th prime whose value is ≡ 5 (mod 7). */
/* The sequence is generated by incrementally testing integers for primality
   and recording the indices of those primes that satisfy the congruence. */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* Cache of computed terms: cache[i] holds a(i+1). */
static seq_t *cache = NULL;
static size_t cache_cap = 0;
static size_t cache_len = 0;

/* List of primes found so far, used for primality testing. */
static uint32_t *primes = NULL;
static size_t primes_cap = 0;
static size_t primes_len = 0;

/* Next integer candidate for primality testing. */
static uint32_t candidate = 2;

/* Ensure cache has enough capacity. */
static void ensure_cache_capacity(size_t needed)
{
    if (needed <= cache_cap) return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 8;
    while (new_cap < needed) new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp && new_cap) abort();
    cache = tmp;
    cache_cap = new_cap;
}

/* Ensure prime list has enough capacity. */
static void ensure_primes_capacity(size_t needed)
{
    if (needed <= primes_cap) return;
    size_t new_cap = primes_cap ? primes_cap * 2 : 8;
    while (new_cap < needed) new_cap <<= 1;
    uint32_t *tmp = (uint32_t *)realloc(primes, new_cap * sizeof(uint32_t));
    if (!tmp && new_cap) abort();
    primes = tmp;
    primes_cap = new_cap;
}

/* Generate the next prime and, if it satisfies the congruence, store its index. */
static void generate_next_prime(void)
{
    /* Find the next prime. */
    while (true) {
        bool is_prime = true;
        uint64_t val = candidate;
        for (size_t i = 0; i < primes_len; ++i) {
            uint32_t p = primes[i];
            uint64_t p_val = p;
            if (p_val * p_val > val) break;
            if (val % p == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) break;
        ++candidate;
    }

    /* Record the prime. */
    ensure_primes_capacity(primes_len + 1);
    primes[primes_len++] = candidate;

    /* If prime % 7 == 5, store its index. */
    if ((candidate % 7) == 5) {
        ensure_cache_capacity(cache_len + 1);
        cache[cache_len++] = (seq_t)primes_len; /* index in the prime list */
    }
    ++candidate;  /* advance to next candidate */
}

/* Generate terms until we have at least target terms cached. */
static void generate_until(size_t target)
{
    while (cache_len < target) generate_next_prime();
}

/* Required function: returns a(n). */
seq_t a(idx_t n)
{
    if (n == 0) return 0;    /* undefined for n = 0, return placeholder */
    generate_until((size_t)n);
    return cache[n - 1];
}
